const squareTitles=[];
function squareTitle(e,size=76,y=160){
  const scene=e.parentNode,words=e.textContent.split(' '),lines=[];let text='';
  e.textContent='';at(e,'x',96);at(e,'y',y);at(e,'font-size',size);
  // Measure the actual bold font once, rather than guessing from character count.
  const measure=el('tspan',{},e);
  for(const word of words){
    const candidate=text?text+' '+word:word;measure.textContent=candidate;
    if(text&&measure.getComputedTextLength()>1408){lines.push(text);text=word;}else text=candidate;
  }
  if(text)lines.push(text);measure.remove();
  lines.forEach((line,i)=>el('tspan',{x:96,dy:i?size*1.13:0},e).textContent=line);
  const holder=el('g',{},S);holder.append(e);squareTitles.push({holder,scene});
}
